-- ============================================================
-- FINGERLING -> SUPABASE POSTGRESQL MIGRATION
-- Compatibility-fixed version
--
-- Preserves the source tables and INSERT data.
-- Legacy MySQL ENUM values that were stored as empty strings are
-- allowed where they actually occur in the source data.
-- ============================================================

-- Fingerling Marketplace: Supabase PostgreSQL migration (FIXED)
-- Generated from the uploaded fingerling_supabase_postgresql.sql.
-- Fixes:
--   * MySQL TINYINT(1) -> PostgreSQL BOOLEAN
--   * Boolean INSERT values 0/1 -> FALSE/TRUE
--   * MySQL zero timestamp -> PostgreSQL NULL
-- Existing CREATE TABLE, INSERT data, foreign keys, indexes, identity sequence
-- synchronization, and update triggers are preserved.
SET search_path TO public;

BEGIN;

CREATE TABLE "admins" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "full_name" varchar(255) NOT NULL,
  "role" varchar(100) DEFAULT 'admin',
  "permissions" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "announcements" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" varchar(255) NOT NULL,
  "content" text NOT NULL,
  "type" text DEFAULT 'info' CHECK ("type" IN ('info','warning','urgent')),
  "target_audience" text DEFAULT 'all' CHECK ("target_audience" IN ('all','customers','suppliers')),
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "audit_log" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer DEFAULT NULL,
  "action" varchar(100) NOT NULL,
  "table_name" varchar(100) DEFAULT NULL,
  "record_id" integer DEFAULT NULL,
  "old_values" text DEFAULT NULL,
  "new_values" text DEFAULT NULL,
  "ip_address" varchar(45) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "cart" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL DEFAULT 1,
  "price_per_piece" decimal(10,2) NOT NULL,
  "added_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "cart_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "quantity" integer NOT NULL DEFAULT 1,
  "price" decimal(10,2) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "categories" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NOT NULL,
  "description" text DEFAULT NULL,
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "conversations" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id" integer NOT NULL,
  "supplier_id" integer NOT NULL,
  "order_id" integer DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "is_archived" boolean DEFAULT false
);


CREATE TABLE "customers" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "middle_initial" varchar(5) DEFAULT NULL,
  "contact_number" varchar(20) DEFAULT NULL,
  "address" text DEFAULT NULL,
  "barangay" varchar(100) DEFAULT NULL,
  "city" varchar(100) DEFAULT NULL,
  "province" varchar(100) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "phone" varchar(20) DEFAULT NULL,
  "postal_code" varchar(20) DEFAULT NULL
);


CREATE TABLE "customer_addresses" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id" integer NOT NULL,
  "label" varchar(100) NOT NULL,
  "recipient_name" varchar(255) NOT NULL,
  "phone" varchar(20) NOT NULL,
  "address_line_1" varchar(255) NOT NULL,
  "address_line_2" varchar(255) DEFAULT NULL,
  "barangay" varchar(100) NOT NULL,
  "city" varchar(100) NOT NULL,
  "province" varchar(100) NOT NULL,
  "postal_code" varchar(20) DEFAULT NULL,
  "is_default" boolean DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "delivery_confirmation_reminders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "reminder_sent_at" timestamp NOT NULL,
  "reminder_type" text NOT NULL CHECK ("reminder_type" IN ('first','second','final'))
);

CREATE TABLE "delivery_proofs" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "rider_name" varchar(255) NOT NULL,
  "rider_phone" varchar(50) NOT NULL,
  "image_path" varchar(500) NOT NULL,
  "submitted_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "supplier_confirmed" boolean DEFAULT false,
  "admin_verified" boolean DEFAULT false
);


CREATE TABLE "feedback" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "customer_id" integer NOT NULL,
  "supplier_id" integer NOT NULL,
  "rating" integer NOT NULL CHECK ("rating" >= 1 and "rating" <= 5),
  "comment" text DEFAULT NULL,
  "supplier_reply" text DEFAULT NULL,
  "image_path" varchar(255) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "inventory" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" integer NOT NULL,
  "species_id" integer NOT NULL,
  "size_category" varchar(20) DEFAULT NULL,
  "stock_quantity" integer NOT NULL DEFAULT 0,
  "price_per_piece" decimal(10,2) NOT NULL,
  "minimum_order" integer DEFAULT 1,
  "availability_status" text DEFAULT 'available' CHECK ("availability_status" IN ('available','out_of_stock','discontinued')),
  "description" text DEFAULT NULL,
  "image_path" varchar(500) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "messages" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "conversation_id" integer NOT NULL,
  "sender_id" integer NOT NULL,
  "receiver_id" integer NOT NULL,
  "message" text NOT NULL,
  "is_auto" boolean NOT NULL DEFAULT false,
  "order_id" integer DEFAULT NULL,
  "is_read" boolean DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "is_unsent" boolean DEFAULT false
);


CREATE TABLE "notifications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "customer_id" integer DEFAULT NULL,
  "title" varchar(255) NOT NULL,
  "message" text NOT NULL,
  "link" varchar(500) DEFAULT NULL,
  "type" text DEFAULT 'system' CHECK ("type" IN ('order','payment','system','promotion')),
  "is_read" boolean DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);




CREATE TABLE "notification_preferences" (
  "user_id" integer NOT NULL,
  "email_orders" boolean DEFAULT true,
  "email_payments" boolean DEFAULT true,
  "email_reviews" boolean DEFAULT true,
  "email_marketing" boolean DEFAULT false
);

CREATE TABLE "orders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_number" varchar(50) NOT NULL,
  "customer_id" integer NOT NULL,
  "supplier_id" integer NOT NULL,
  "total_amount" decimal(10,2) NOT NULL,
  "admin_commission" decimal(10,2) DEFAULT NULL,
  "status" text NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','confirmed','confirmed_and_paid','preparing','scheduled_for_delivery','out_for_delivery','pending_supplier_review','pending_admin_verification','delivered','cancelled','archived')),
  "delivery_address" text DEFAULT NULL,
  "delivery_date" date DEFAULT NULL,
  "delivery_worker" varchar(255) DEFAULT NULL,
  "delivery_worker_contact" varchar(50) DEFAULT NULL,
  "eta_time" varchar(50) DEFAULT NULL,
  "notes" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "tracking_number" varchar(50) DEFAULT NULL,
  "expected_delivery_date" date DEFAULT NULL,
  "delivery_phone" varchar(20) DEFAULT NULL,
  "delivery_notes" text DEFAULT NULL,
  "payment_method" text DEFAULT 'cod' CHECK ("payment_method" IN ('gcash','paypal','cod') OR "payment_method" = ''),
  "payment_reference" varchar(255) DEFAULT NULL,
  "payment_status" varchar(50) DEFAULT NULL,
  "subtotal" decimal(10,2) NOT NULL DEFAULT 0.00,
  "delivery_fee" decimal(10,2) NOT NULL DEFAULT 0.00,
  "cancelled_at" timestamp NULL DEFAULT NULL,
  "cancellation_reason" text DEFAULT NULL,
  "delivery_type" text DEFAULT NULL CHECK ("delivery_type" IN ('truck','boat')),
  "payment_fee" decimal(10,2) DEFAULT 0.00,
  "delivery_date_start" date DEFAULT NULL,
  "delivery_date_end" date DEFAULT NULL,
  "delivery_time_selected" timestamp DEFAULT NULL,
  "customer_confirmed_delivery" boolean DEFAULT false,
  "customer_confirmed_at" timestamp DEFAULT NULL,
  "reminder_sent_at" timestamp DEFAULT NULL,
  "auto_confirmed_delivery" boolean DEFAULT false,
  "auto_confirmed_at" timestamp DEFAULT NULL,
  "archived_at" timestamp DEFAULT NULL,
  "payment_deadline" timestamp DEFAULT NULL,
  "supplier_delivery_from" date DEFAULT NULL,
  "supplier_delivery_to" date DEFAULT NULL,
  "customer_selected_delivery_date" date DEFAULT NULL,
  "delivery_selection_deadline" timestamp DEFAULT NULL,
  "supplier_accept_deadline" timestamp DEFAULT NULL,
  "supplier_accepted_at" timestamp DEFAULT NULL,
  "delivery_token" varchar(100) DEFAULT NULL,
  "token_expires_at" timestamp DEFAULT NULL,
  "token_used" boolean DEFAULT false,
  "delivery_status" varchar(50) DEFAULT 'pending'
);


CREATE TABLE "order_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "inventory_id" integer NOT NULL,
  "quantity" integer NOT NULL,
  "unit_price" decimal(10,2) NOT NULL,
  "subtotal" decimal(10,2) NOT NULL
);


CREATE TABLE "order_status_history" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "status" varchar(50) NOT NULL,
  "previous_status" varchar(50) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "order_tracking" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "status" varchar(50) NOT NULL,
  "title" varchar(255) NOT NULL,
  "description" text DEFAULT NULL,
  "location" varchar(255) DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "password_resets" (
  "email" varchar(255) NOT NULL,
  "token" varchar(64) NOT NULL,
  "expires_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "payments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "payment_method" varchar(50) NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "currency" varchar(10) DEFAULT 'PHP',
  "signature" varchar(255) DEFAULT NULL,
  "transaction_id" varchar(255) DEFAULT NULL,
  "payer_email" varchar(255) DEFAULT NULL,
  "status" varchar(50) DEFAULT 'completed',
  "payment_date" timestamp DEFAULT CURRENT_TIMESTAMP,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "paypal_orders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "paypal_order_id" varchar(255) NOT NULL,
  "order_id" integer NOT NULL,
  "customer_id" integer NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "status" varchar(50) DEFAULT 'CREATED',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "pending_orders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id" integer NOT NULL,
  "paypal_order_id" varchar(255) NOT NULL,
  "authorization_id" varchar(255) NOT NULL,
  "total" decimal(10,2) NOT NULL,
  "cart_data" text NOT NULL,
  "status" text DEFAULT 'pending' CHECK ("status" IN ('pending','confirmed','cancelled','expired')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expires_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP + interval '7 days')
);


CREATE TABLE "phone_verifications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "phone" varchar(20) NOT NULL,
  "otp" varchar(255) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "verified" boolean NOT NULL DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "proof_of_delivery" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "supplier_message" text DEFAULT NULL,
  "photo_path" varchar(500) DEFAULT NULL,
  "submitted_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "customer_notified_at" timestamp DEFAULT NULL,
  "auto_confirmed_at" timestamp DEFAULT NULL
);


CREATE TABLE "refunds" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "reason" text NOT NULL,
  "status" text DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected','processed')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "settings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "setting_key" varchar(100) NOT NULL,
  "setting_value" text DEFAULT NULL,
  "description" text DEFAULT NULL,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "species" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NOT NULL,
  "scientific_name" varchar(255) DEFAULT NULL,
  "description" text DEFAULT NULL,
  "image_url" varchar(500) DEFAULT NULL,
  "category" varchar(100) DEFAULT NULL,
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "category_id" integer DEFAULT NULL
);


CREATE TABLE "species_backup" (
  "id" integer NOT NULL DEFAULT 0,
  "name" varchar(255) NOT NULL,
  "scientific_name" varchar(255) DEFAULT NULL,
  "description" text DEFAULT NULL,
  "image_url" varchar(500) DEFAULT NULL,
  "category" varchar(100) DEFAULT NULL,
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "category_id" integer DEFAULT NULL
);


CREATE TABLE "suppliers" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "business_name" varchar(255) NOT NULL,
  "permit_file" varchar(255) DEFAULT NULL,
  "permit_expiry" date DEFAULT NULL,
  "owner_name" varchar(255) NOT NULL,
  "contact_number" varchar(20) DEFAULT NULL,
  "business_address" text DEFAULT NULL,
  "purok" varchar(100) DEFAULT NULL,
  "barangay" varchar(100) DEFAULT NULL,
  "city" varchar(100) DEFAULT NULL,
  "province" varchar(100) DEFAULT NULL,
  "latitude" decimal(10,8) DEFAULT NULL,
  "longitude" decimal(11,8) DEFAULT NULL,
  "valid_id" varchar(255) DEFAULT NULL,
  "certifications" text DEFAULT NULL,
  "description" text DEFAULT NULL,
  "rating" decimal(3,2) DEFAULT 0.00,
  "total_ratings" integer DEFAULT 0,
  "status" text DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected','suspended') OR "status" = ''),
  "suspension_reason" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "supplier_status" text DEFAULT 'pending' CHECK ("supplier_status" IN ('pending','approved','rejected','suspended') OR "supplier_status" = ''),
  "store_name" varchar(255) DEFAULT NULL,
  "contact_name" varchar(255) DEFAULT NULL,
  "full_address" text DEFAULT NULL,
  "product_description" text DEFAULT NULL,
  "pond_photo" varchar(255) DEFAULT NULL,
  "logo_url" varchar(500) DEFAULT NULL,
  "supports_truck" boolean DEFAULT true,
  "supports_boat" boolean DEFAULT false
);


CREATE TABLE "supplier_appeals" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" integer NOT NULL,
  "suspension_reason" text DEFAULT NULL,
  "appeal_message" text NOT NULL,
  "status" text DEFAULT 'pending' CHECK ("status" IN ('pending','reviewed','resolved')),
  "admin_notes" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "supplier_notes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" integer NOT NULL,
  "admin_id" integer NOT NULL,
  "note_type" text DEFAULT 'general' CHECK ("note_type" IN ('approval','rejection','suspension','general','warning','compliance')),
  "note_title" varchar(255) DEFAULT NULL,
  "note_content" text NOT NULL,
  "is_internal" boolean DEFAULT true,
  "priority" text DEFAULT 'medium' CHECK ("priority" IN ('low','medium','high','urgent')),
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','resolved','archived')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(255) NOT NULL,
  "password_hash" varchar(255) DEFAULT NULL,
  "user_type" text NOT NULL CHECK ("user_type" IN ('customer','supplier','admin')),
  "google_id" varchar(255) DEFAULT NULL,
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive','pending','rejected')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "current_session_id" varchar(64) DEFAULT NULL,
  "session_last_activity" timestamp DEFAULT NULL
);


CREATE TABLE "user_email_verifications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "code_hash" varchar(255) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "attempts" integer NOT NULL DEFAULT 0,
  "verified_at" timestamp DEFAULT NULL,
  "sent_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "user_notification_settings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer NOT NULL,
  "email_orders" boolean DEFAULT true,
  "email_promotions" boolean DEFAULT false,
  "sms_orders" boolean DEFAULT false,
  "sms_promotions" boolean DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "user_otps" (
  "user_id" integer NOT NULL,
  "otp" varchar(6) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "user_2fa_otps" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "user_id" integer NOT NULL UNIQUE,
  "otp_code" varchar(255) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "attempts" integer NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "remember_tokens" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "user_id" integer NOT NULL,
  "token" varchar(255) NOT NULL,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "user_sessions" (
  "id" varchar(128) NOT NULL,
  "user_id" integer NOT NULL,
  "ip_address" varchar(45) DEFAULT NULL,
  "user_agent" text DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expires_at" timestamp NULL DEFAULT NULL
);


CREATE TABLE "withdrawals" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" integer NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "method" text NOT NULL CHECK ("method" IN ('gcash','paypal')),
  "account_info" varchar(255) NOT NULL,
  "status" text NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','completed','cancelled')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "withdrawal_appeals" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "withdrawal_id" integer NOT NULL,
  "supplier_id" integer NOT NULL,
  "reason" text NOT NULL,
  "proof_file" varchar(255) DEFAULT NULL,
  "status" text NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected')),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE "xendit_invoices" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoice_id" varchar(255) NOT NULL,
  "invoice_url" text NOT NULL,
  "xendit_status" varchar(50) DEFAULT 'pending',
  "expiry" timestamp DEFAULT NULL,
  "order_id" integer DEFAULT NULL,
  "customer_id" integer DEFAULT NULL,
  "amount" decimal(10,2) NOT NULL,
  "external_id" varchar(255) DEFAULT NULL,
  "payment_method" varchar(50) DEFAULT 'Xendit',
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE "admins" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "admins__user_id" ON "admins" ("user_id");

ALTER TABLE "announcements" ADD PRIMARY KEY ("id");

ALTER TABLE "audit_log" ADD PRIMARY KEY ("id");
CREATE INDEX "audit_log__user_id" ON "audit_log" ("user_id");

ALTER TABLE "cart" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "cart__unique_customer_product" ON "cart" ("customer_id","product_id");
CREATE INDEX "cart__product_id" ON "cart" ("product_id");
CREATE INDEX "cart__idx_cart_customer" ON "cart" ("customer_id");

ALTER TABLE "cart_items" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "cart_items__unique_cart_item" ON "cart_items" ("customer_id","product_id");
CREATE INDEX "cart_items__idx_customer_id" ON "cart_items" ("customer_id");
CREATE INDEX "cart_items__idx_product_id" ON "cart_items" ("product_id");

ALTER TABLE "categories" ADD PRIMARY KEY ("id");

ALTER TABLE "conversations" ADD PRIMARY KEY ("id");
CREATE INDEX "conversations__order_id" ON "conversations" ("order_id");
CREATE INDEX "conversations__idx_conversations_customer" ON "conversations" ("customer_id");
CREATE INDEX "conversations__idx_conversations_supplier" ON "conversations" ("supplier_id");
CREATE INDEX "conversations__idx_conversations_archived" ON "conversations" ("is_archived");

ALTER TABLE "customers" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "customers__user_id" ON "customers" ("user_id");

ALTER TABLE "customer_addresses" ADD PRIMARY KEY ("id");
CREATE INDEX "customer_addresses__customer_id" ON "customer_addresses" ("customer_id");

ALTER TABLE "delivery_confirmation_reminders" ADD PRIMARY KEY ("id");
CREATE INDEX "delivery_confirmation_reminders__idx_order_id" ON "delivery_confirmation_reminders" ("order_id");
CREATE INDEX "delivery_confirmation_reminders__idx_reminder_sent_at" ON "delivery_confirmation_reminders" ("reminder_sent_at");

ALTER TABLE "delivery_proofs" ADD PRIMARY KEY ("id");
CREATE INDEX "delivery_proofs__order_id" ON "delivery_proofs" ("order_id");

ALTER TABLE "feedback" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "feedback__unique_order_feedback" ON "feedback" ("order_id");
CREATE INDEX "feedback__customer_id" ON "feedback" ("customer_id");
CREATE INDEX "feedback__supplier_id" ON "feedback" ("supplier_id");

ALTER TABLE "inventory" ADD PRIMARY KEY ("id");
CREATE UNIQUE INDEX "inventory__unique_supplier_species_size" ON "inventory" ("supplier_id","species_id","size_category");
CREATE INDEX "inventory__species_id" ON "inventory" ("species_id");
CREATE INDEX "inventory__idx_inventory_supplier_available" ON "inventory" ("supplier_id","availability_status");

ALTER TABLE "messages" ADD PRIMARY KEY ("id");
