-- Recreate MySQL ON UPDATE CURRENT_TIMESTAMP behavior.
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS "announcements__set_updated_at" ON "announcements";
CREATE TRIGGER "announcements__set_updated_at" BEFORE UPDATE ON "announcements" FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
